\begin{aligned}
\text{设通解形式为：} \quad x(t) &= A \cos(\omega t + \phi) \\[6pt]
\text{对时间 } t \text{ 求一阶导数（速度）：} \quad \frac{\mathrm{d}x}{\mathrm{d}t} &= -A\omega \sin(\omega t + \phi) \\[6pt]
\text{求二阶导数（加速度）：} \quad \frac{\mathrm{d}^2x}{\mathrm{d}t^2} &= -A\omega^2 \cos(\omega t + \phi) = -\omega^2 x \\[8pt]
\text{代入微分方程运动项：} \quad \frac{\mathrm{d}^2x}{\mathrm{d}t^2} + \omega^2 x &= -\omega^2 x + \omega^2 x \equiv 0
\end{aligned}

\begin{aligned}
\langle E_k \rangle &= \frac{1}{T} \int_0^T \frac{1}{2} m v^2 \,\mathrm{d}t = \frac{1}{2} m A^2 \omega^2 \cdot \frac{1}{T} \int_0^T \sin^2(\omega t + \varphi) \,\mathrm{d}t = \frac{1}{4} k A^2 = \frac{1}{2} E \\[8pt]
\langle E_p \rangle &= \frac{1}{T} \int_0^T \frac{1}{2} k x^2 \,\mathrm{d}t = \frac{1}{2} k A^2 \cdot \frac{1}{T} \int_0^T \cos^2(\omega t + \varphi) \,\mathrm{d}t = \frac{1}{4} k A^2 = \frac{1}{2} E
\end{aligned}

\begin{aligned}
E &= E_k + E_p = \frac{1}{2} m (L \dot{\theta})^2 + m g L (1 - \cos\theta) = \text{常数} \\[6pt]
\text{对时间求导：} \quad & \frac{\mathrm{d}E}{\mathrm{d}t} = m L^2 \dot{\theta} \ddot{\theta} + m g L \dot{\theta} \sin\theta = 0 \\[6pt]
\text{消去 } m L^2 \dot{\theta} \text{，小角度 } \sin\theta \approx \theta \text{：} \quad & \ddot{\theta} + \frac{g}{L} \theta = 0 \implies \omega = \sqrt{\frac{g}{L}} \\[6pt]
\text{简谐振动周期：} \quad & T = \frac{2\pi}{\omega} = 2\pi \sqrt{\frac{L}{g}}
\end{aligned}
